-- 3. Reset Sequences
SELECT setval('categories_id_seq', (SELECT MAX(id) FROM categories));
SELECT setval('users_id_seq', (SELECT MAX(id) FROM users));
SELECT setval('videos_id_seq', (SELECT MAX(id) FROM videos));

-- 4. Enable RLS
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE videos ENABLE ROW LEVEL SECURITY;

-- 5. Create Policies
-- Public read access
CREATE POLICY "Public read access for categories" ON categories FOR SELECT USING (true);
CREATE POLICY "Public read access for videos" ON videos FOR SELECT USING (true);

-- Authenticated access for modification (Admins)
CREATE POLICY "Auth write access for categories" ON categories FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Auth write access for videos" ON videos FOR ALL USING (auth.role() = 'authenticated');
CREATE POLICY "Auth read/write access for users" ON users FOR ALL USING (auth.role() = 'authenticated');
